from __future__ import annotations

import logging
from typing import Any, Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .snmp import SnmpPdu


class HPE(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type HPE"""

    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 10,
        snmp_user: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(host, timeout, snmp_user)
        self._version = 3
        self._key = ".1.3.6.1.4.1.232.165.11.5.2.1"

        self.operations = {
            DeviceStatus.ON: self._key + ".3.1",
            DeviceStatus.OFF: self._key + ".2.1",
            "get_status": self._key + ".1.1",
        }

    @property
    def _port_setting(self):
        return {DeviceStatus.ON: "2", DeviceStatus.OFF: "1"}

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port, action):
        oid = self.operations[action]
        if port in range(1, 25):
            return f"{oid}.{port}"
        else:
            raise BadPortNumber(f"Port number is invalid: {port}")

    def _set_port_status(self, port, status):
        snmp_msg = self._build_snmp_oid(port=port, action=status)
        logging.info(f"SNMP: Setting port to {status}: {port}")
        self._execute_set_cmd(status, snmp_msg)

    def get_port_status(self, port):
        logging.info(f"SNMP: Fetching status of port: {port}")
        snmp_msg = self._build_snmp_oid(port=port, action="get_status")
        port_value = self._execute_get_cmd(snmp_msg)
        return self._reversed_port_settings[port_value]
